<template>
  <ToolbarContainer :config="componentConfig" />
</template>

<script>
import config from '@/components/OperationsView/OperationsToolbar/config'
import ToolbarContainer from '@/components/shared/ToolbarContainer'

export default {
  name: 'OperationsViewMainToolbar',
  components: { ToolbarContainer },
  data() {
    return {
      config,
    }
  },
  computed: {
    componentConfig() {
      return config()
    },
  },
}
</script>
