<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import vendorsViewActions from '@/store/vendorsView/actions.types'

import setDialogConfig from '@/components/VendorsView/VendorDetailDialog/Footer/PurchaseDraftDialog/config'
import DialogCard from '@/components/shared/DialogCard.vue'

export default {
  name: 'PurchaseDraftDialog',
  components: { DialogCard },
  data() {
    return {
      addingPurchase: false,
    }
  },
  computed: {
    ...mapState('vendorsView', ['purchaseDraftDialog', 'selectedVendor']),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.purchaseDraftDialog.isOpen,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          newPurchase: this.newPurchase,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('vendorsView', [
      vendorsViewActions.togglePurchaseDraftDialog,
    ]),
    closeDialog() {
      this[vendorsViewActions.togglePurchaseDraftDialog]()
    },
    purchaseListener(event, payload) {
      const purchaseReplies = PURCHASES_DB_API_EVENTS.events
      const replies = {
        [purchaseReplies.delete.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_purchase',
            category: this.$route.name,
            screen: 'PurchaseDraftDialog',
            name: 'Add new purchase',
          })
          if (isNil(this.purchaseDraftDialog.purchaseOld?.purchaseOld)) {
            this.$loading.show('createPurchase')
            rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
              event: PURCHASES_DB_API_EVENTS.events.add.name,
              data: {
                purchaseData: {
                  vendorId: this.selectedVendor.id,
                  status: 1,
                  source: 1,
                  promotion: 0,
                  items: [],
                  returnItems: [],
                  cost: 0,
                },
              },
            })
          } else {
            const {
              purchaseItemsNotInInventory,
              purchaseOld,
            } = this.purchaseDraftDialog.purchaseOld
            if (isNil(purchaseItemsNotInInventory)) {
              this.$loading.show('createPurchase')
              rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
                event: PURCHASES_DB_API_EVENTS.events.repeatPurchase.name,
                data: {
                  oldPurchase: purchaseOld,
                  purchaseData: this.purchaseDraftDialog.purchaseSelected,
                },
              })
            } else {
              rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
                event: ADD_PRODUCT_EVENTS.events.addProductsFromMLP.name,
                data: {
                  items: purchaseItemsNotInInventory,
                  property: 'prod_name',
                  limit: 1,
                },
              })
            }
          }
        },
        [purchaseReplies.delete.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'PurchaseDraftDialog',
            name: 'Error deleting purchase',
          })
          this.addingPurchase = false
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          )
        },
        [purchaseReplies.add.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'add_purchase',
            category: this.$route.name,
            screen: 'PurchaseDraftDialog',
            name: 'Go to purchase',
          })
          this.addingPurchase = false
        },
        [purchaseReplies.add.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'PurchaseDraftDialog',
            name: 'Error adding purchase',
          })
          this.addingPurchase = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    newPurchase() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'PurchaseDraftDialog',
        name: 'Create new purchase',
      })
      if (this.addingPurchase) return
      this.addingPurchase = true
      const lastPurchase = this.selectedVendor.purchases[0]
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.delete.name,
        data: {
          purchase: lastPurchase,
        },
      })
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
    if (this.purchaseDraftDialog.isOpen) this.closeDialog()
  },
}
</script>
