<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import CASH_OPERATIONS_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'

import { getNow, getDateWithFormat, addDays } from '@/tools/dates'

import rendererEventsService from '@/services/renderer/rendererEvents'

import operationsViewActions from '@/store/operationsView/actions.types'
import operationsActions from '@/store/operations/actions.types'

import config from '@/components/OperationsView/OperationsToolbar/Filters/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'OperationsToolbarFilter',
  components: { ToolBar },
  data() {
    return {
      config,
    }
  },
  computed: {
    ...mapState('operationsView', ['filters']),
    ...mapState('operations', ['operations']),
    componentConfig: function() {
      return config(
        { filters: this.filters },
        {
          setDateRange: this.setDateRange,
          initializeDateRangeFilter: this[
            operationsViewActions.initializeDateRangeFilter
          ],
          setGroup: this[operationsViewActions.setGroupFilter],
          setSelectedOperationTypes: this[
            operationsViewActions.setOperationTypesFilter
          ],
          setSearchFilter: this[operationsViewActions.setSearchFilter],
        }
      )
    },
  },
  methods: {
    ...mapActions('operationsView', [
      operationsViewActions.setDateRangeFilter,
      operationsViewActions.initializeDateRangeFilter,
      operationsViewActions.setGroupFilter,
      operationsViewActions.setOperationTypesFilter,
      operationsViewActions.setSearchFilter,
    ]),
    ...mapActions('operations', [
      operationsActions.fetchOperationsBetweenDates,
      operationsActions.setOperationsFetching,
      operationsActions.setOperationsError,
    ]),
    setDateRange(value) {
      const today = getDateWithFormat(getNow(false), 'YYYY-MM-DD')
      const fromValue = value[value.length === 2 && value[0] > value[1] ? 1 : 0]
      const toValue = value[value.length === 2 && value[0] > value[1] ? 0 : 1]
      const fromState = getDateWithFormat(
        this.operations[this.operations.length - 1].date,
        'YYYY-MM-DD'
      )
      const toState = getDateWithFormat(this.operations[0].date, 'YYYY-MM-DD')
      if (fromValue < today) {
        if (fromValue < fromState) {
          this[operationsActions.setOperationsFetching](true)
          rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
            event: CASH_OPERATIONS_EVENTS.events.getOperationsBetweenDates.name,
            data: {
              fromDate: fromValue,
              toDate: getDateWithFormat(addDays(toState, 1), 'YYYY-MM-DD'),
            },
          })
        }
        if (fromValue > toState) {
          this[operationsActions.setOperationsFetching](true)
          rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
            event: CASH_OPERATIONS_EVENTS.events.getOperationsBetweenDates.name,
            data: {
              fromDate: fromState,
              toDate: getDateWithFormat(addDays(toValue, 1), 'YYYY-MM-DD'),
            },
          })
        }
      }
      this[operationsViewActions.setDateRangeFilter](value)
    },
  },
  mounted() {
    if (testMode) return
    rendererEventsService.subscribe(
      CASH_OPERATIONS_EVENTS.replyChannel,
      (event, payload) => {
        const events = CASH_OPERATIONS_EVENTS.events
        const replies = {
          [events.getOperationsBetweenDates.replies.success]: () =>
            this[operationsActions.fetchOperationsBetweenDates](payload.data),
          [events.getOperationsBetweenDates.replies.error]: () => {
            this[operationsActions.setOperationsError](payload.data)
            this[operationsActions.setOperationsFetching](false)
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(
      CASH_OPERATIONS_EVENTS.replyChannel
    )
  },
}
</script>
