<template>
  <v-container fluid class="operations-view" id="operations-view">
    <!-- View toolbar  -->
    <v-row no-gutters>
      <v-col
        class="operations-view__filter-toolbar px-6 pt-6"
        id="operations-view__filter-toolbar"
      >
        <OperationsToolBar />
      </v-col>
    </v-row>
    <!-- List view -->
    <v-row no-gutters>
      <v-col
        class="operations-view__operations-list"
        id="operations-view__operations-list"
        :style="{
          height: `calc(100vh - ${getOperationsListStyles}px)`,
        }"
      >
        <OperationsList />
        <RepeatPurchaseConfirmDialog
          v-if="repeatPurchaseConfirmDialog.isOpen"
        />
        <PurchaseDraftDialog v-if="purchaseDraftDialog.isOpen" />
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { isNil } from 'ramda'
import { mapActions, mapState } from 'vuex'

import { testMode, operationsLimit } from '@/config/env'
import CASH_OPERATIONS_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'

import rendererEventsService from '@/services/renderer/rendererEvents'

import operationsActions from '@/store/operations/actions.types'
import vendorsActions from '@/store/vendors/actions.types'
import vendorsViewActions from '@/store/vendorsView/actions.types'
import operationsViewActions from '@/store/operationsView/actions.types'

import OperationsToolBar from '@/components/OperationsView/OperationsToolbar'
import OperationsList from '@/components/OperationsView/OperationsList'
import RepeatPurchaseConfirmDialog from '@/components/VendorsView/VendorDetailDialog/LastOrdersTab/RepeatPurchaseConfirmDialog'
import PurchaseDraftDialog from '@/components/VendorsView/VendorDetailDialog/Footer/PurchaseDraftDialog'

export default {
  name: 'Operations',
  components: {
    OperationsToolBar,
    OperationsList,
    RepeatPurchaseConfirmDialog,
    PurchaseDraftDialog,
  },
  data() {
    return {
      layoutCommonElementsHeight: 0,
    }
  },
  computed: {
    ...mapState('vendorsView', [
      'repeatPurchaseConfirmDialog',
      'selectedVendor',
      'purchaseDraftDialog',
    ]),
    ...mapState('vendors', ['data']),
    getOperationsListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    ...mapActions('operations', [
      operationsActions.fetchOperations,
      operationsActions.emptyOperations,
      operationsActions.setOperationsFetching,
      operationsActions.setOperationsError,
    ]),
    ...mapActions('vendors', [
      vendorsActions.setVendors,
      vendorsActions.setVendorsError,
      vendorsActions.setVendorsFetching,
    ]),
    ...mapActions('vendorsView', [vendorsViewActions.setSelectedVendor]),
    ...mapActions('operationsView', [
      operationsViewActions.setOperationTypesFilter,
    ]),
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'operations-view'
      )
      const operationsViewToolbar = document.getElementById(
        'operations-view__filter-toolbar'
      ).offsetHeight
      this.layoutCommonElementsHeight =
        layoutComponentsHeight + operationsViewToolbar
    },
    cashOperationsListener(event, payload) {
      const events = CASH_OPERATIONS_EVENTS.events
      const replies = {
        [events.getLastNOperations.replies.success]: () =>
          this[operationsActions.fetchOperations](payload.data),
        [events.getLastNOperations.replies.error]: () => {
          this[operationsActions.setOperationsError](payload.data)
          this[operationsActions.setOperationsFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    purchaseListener(event, payload) {
      const events = PURCHASES_DB_API_EVENTS.events
      const replies = {
        [events.repeatPurchase.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'repeat_purchase',
            category: this.$route.name,
            screen: 'RepeatPurchaseConfirmDialog',
            name: 'Go to purchases',
          })
          rendererEventsService.send(ENTITIES_EVENTS.channel, {
            event: ENTITIES_EVENTS.events.getAllByEntities.name,
            data: {
              entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
              replyName: 'fetchVendors',
            },
          })
          setTimeout(() => {
            this.$loading.hide()
            this.$router.push({ path: '/app/vendors/purchases' })
          }, 700)
        },
        [events.repeatPurchase.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: this.$route.name,
            screen: 'RepeatPurchaseConfirmDialog',
            name: 'Error on repeat purchase',
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    entitiesListener(event, payload) {
      const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
      const replies = {
        [`${getAllReplies.success}-fetchVendors`]: async () => {
          await this[vendorsActions.setVendors](payload.data)
          if (isNil(this.selectedVendor)) return
          const vendorUpdated = this.data.vendors.find(
            ({ id }) => id === this.selectedVendor.id
          )
          this[vendorsViewActions.setSelectedVendor](vendorUpdated)
        },
        [`${getAllReplies.error}-fetchVendors`]: () => {
          this[vendorsActions.setVendorsError](payload.data)
          this[vendorsActions.setVendorsFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.cashOperationsListener
    )
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
  },
  mounted() {
    this[operationsActions.setOperationsFetching](true)
    rendererEventsService.send(CASH_OPERATIONS_EVENTS.channel, {
      event: CASH_OPERATIONS_EVENTS.events.getLastNOperations.name,
      data: operationsLimit,
    })
    this.getLayoutHeight()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CASH_OPERATIONS_EVENTS.replyChannel,
      this.cashOperationsListener
    )
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
  },
  destroyed() {
    this[operationsActions.emptyOperations]()
    this[operationsViewActions.setOperationTypesFilter]([])
  },
}
</script>

<style lang="scss" scoped>
.operations-view {
  height: 100%;
  .operations-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .operations-view__products-list {
    width: 100%;
  }
}
</style>
