const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'vendorsView.dialogs.repeatPurchaseConfirmDialog.title',
    messages: ['vendorsView.dialogs.repeatPurchaseConfirmDialog.message'],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    acceptButtonText:
      'vendorsView.dialogs.repeatPurchaseConfirmDialog.buttons.continue',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 230,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'RepeatPurchaseConfirmDialog',
        name: 'Cancel',
      })
      methods.closeDialog()
    },
    onClickAccept: () => {
      methods.processPurchase()
    },
  },
})

export default setConfig
