<template>
  <div class="fill-height px-3">
    <PaginatedList :config="componentConfig" />
    <OperationDetail v-if="operationDetailDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'
import { idOperations } from '@/config/cashOperationsVariables'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import operationsViewActions from '@/store/operationsView/actions.types'

import setConfig from '@/components/OperationsView/OperationsList/config'
import PaginatedList from '@/components/shared/PaginatedTable'
import OperationDetail from '@/components/OperationsView/OperationDetail'

export default {
  name: 'OperationsList',
  components: { PaginatedList, OperationDetail },
  computed: {
    ...mapState('app', ['windowSize']),
    ...mapState('operations', ['fetching']),
    ...mapState('operationsView', ['filters', 'operationDetailDialog']),
    ...mapState('users', ['users']),
    ...mapState('customers', ['data']),
    ...mapGetters('operations', ['getFilteredData']),
    ...mapState('vendors', {
      vendors: state => state.data.vendors,
    }),
    componentConfig() {
      return setConfig(
        {
          items: this.getFilteredData,
          users: this.users,
          windowHeight: this.windowSize.y,
          fetching: this.fetching,
          filters: this.filters,
        },
        {
          context: this,
          getTranslatedText: this.getTranslatedText,
          openOperationDetailDialog: this.openOperationDetailDialog,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('operationsView', [
      operationsViewActions.setOperationDetailDialogStatus,
    ]),
    openOperationDetailDialog(operation) {
      switch (operation.operationType) {
        case idOperations.ID_OPERATION_CASH_SALE:
        case idOperations.ID_OPERATION_CREDIT_SALE:
        case idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE:
          this.getOperationDetails({
            operation,
            customers: this.data.customers,
          })
          break
        case idOperations.ID_OPERATION_CASH_PURCHASE:
        case idOperations.ID_OPERATION_CREDIT_PURCHASE:
          this.getOperationDetails({
            operation,
            vendors: this.vendors,
          })
          break
        case idOperations.ID_OPERATION_OWNER_SALE:
          this.getOperationDetails({
            operation,
          })
          break
        case idOperations.ID_OPERATION_EXPENSE:
          this.getOperationDetails({ operation })
          break
        case idOperations.ID_OPERATION_ADDCASH:
        case idOperations.ID_OPERATION_TAKECASH:
          if (!operation.extraInfo) {
            break
          }
          this.getOperationDetails({ operation })
          break
      }
    },
    getOperationDetails(data) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Operations',
        screen: 'OperationsList',
        name: 'Get operation details',
      })
      this.$loading.show('loadOperationDetails')
      rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
        event: CASH_OPERATIONS_DB_API_EVENTS.events.getOperationDetail.name,
        data,
      })
    },
  },
  mounted() {
    if (testMode) return
    rendererEventsService.subscribe(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      async (event, payload) => {
        const events = CASH_OPERATIONS_DB_API_EVENTS.events
        const replies = {
          [events.getOperationDetail.replies.success]: () => {
            this.$track({
              type: 'system',
              action: 'get_operation',
              category: 'Operations',
              screen: 'OperationsList',
              name: 'Open operation details',
            })
            this[operationsViewActions.setOperationDetailDialogStatus]({
              isOpen: true,
              operationSelected: payload.data,
            })
            this.$loading.hide()
          },
          [events.getOperationDetail.replies.error]: () => {
            this.$loading.hide()
            this.$track({
              type: 'system',
              action: 'error',
              category: 'Operations',
              screen: 'OperationsList',
              name: 'Error getting operation details',
            })
            notificationsService.showError(
              payload.data.errorMsg,
              this.$vuetify.lang
            )
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel
    )
  },
}
</script>
