<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isEmpty, isNil } from 'ramda'

import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import { getObjectCopy } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import vendorsViewActions from '@/store/vendorsView/actions.types'
import productsActions from '@/store/products/actions.types'

import setDialogConfig from '@/components/VendorsView/VendorDetailDialog/LastOrdersTab/RepeatPurchaseConfirmDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'RepeatPurchaseConfirmDialog',
  components: { DialogCard },
  data() {
    return {
      newPurchase: {
        vendorId: null,
        status: 1,
        source: 1,
        promotion: 0,
        items: [],
        cost: null,
      },
    }
  },
  computed: {
    ...mapState('vendorsView', {
      selectedVendor: state => state.selectedVendor,
      purchase: state =>
        getObjectCopy(state.repeatPurchaseConfirmDialog.purchaseSelected),
      isOpen: state => state.repeatPurchaseConfirmDialog.isOpen,
    }),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.isOpen,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          processPurchase: this.processPurchase,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('vendorsView', [
      vendorsViewActions.toggleRepeatPurchaseConfirmDialog,
      vendorsViewActions.togglePurchaseDraftDialog,
    ]),
    ...mapActions('products', [
      productsActions.addProductFromMLP,
      productsActions.removeProductFromMlpData,
    ]),
    closeDialog() {
      this[vendorsViewActions.toggleRepeatPurchaseConfirmDialog]()
    },
    hasPurchaseInDraft() {
      const lastPurchase = this.selectedVendor.purchases[0]
      if (isNil(lastPurchase)) return false
      return lastPurchase.status === '1'
    },
    processPurchase() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'RepeatPurchaseConfirmDialog',
        name: 'Confirm',
      })
      const purchaseItemsNotInInventory = this.getPurchaseItemsNotExistInInventory()
      if (isEmpty(purchaseItemsNotInInventory)) {
        if (this.hasPurchaseInDraft()) {
          this.$track({
            type: 'system',
            action: 'purchase_draft',
            category: this.$route.name,
            screen: 'RepeatPurchaseConfirmDialog',
            name: 'Show purchase in draft',
          })
          this[vendorsViewActions.togglePurchaseDraftDialog]({
            purchase: this.newPurchase,
            purchaseOld: { purchaseOld: this.purchase },
          })
          return
        }
        this.$loading.show('createPurchase')
        rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
          event: PURCHASES_DB_API_EVENTS.events.repeatPurchase.name,
          data: {
            oldPurchase: this.purchase,
            purchaseData: this.newPurchase,
          },
        })
        return
      }
      if (this.hasPurchaseInDraft()) {
        this.$track({
          type: 'system',
          action: 'purchase_draft',
          category: this.$route.name,
          screen: 'RepeatPurchaseConfirmDialog',
          name: 'Show purchase in draft',
        })
        this[vendorsViewActions.togglePurchaseDraftDialog]({
          purchase: this.newPurchase,
          purchaseOld: {
            purchaseOld: this.purchase,
            purchaseItemsNotInInventory,
          },
        })
        return
      }
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductsFromMLP.name,
        data: {
          items: purchaseItemsNotInInventory,
          property: 'prod_name',
          limit: 1,
        },
      })
    },
    getPurchaseItemsNotExistInInventory() {
      const purchaseItemsNotInInventory = []
      this.purchase.items.forEach(purchaseItem => {
        const product = this.products.find(product => {
          if (product.id === purchaseItem.product_id) return product
          if (product.name === purchaseItem.product_name) {
            purchaseItem.product_id = product.id
            purchaseItem.product_stock = product.quantity
            return product
          }
        })
        if (isNil(product)) purchaseItemsNotInInventory.push(purchaseItem)
      })
      return purchaseItemsNotInInventory
    },
    async purchaseListener(event, payload) {
      const purchaseOrderItemEventsReplies =
        PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.getAllByPurchaseId.replies
      const replies = {
        [purchaseOrderItemEventsReplies.success]: () => {
          this.purchase['items'] = payload.data.purchaseItems
        },
        [purchaseOrderItemEventsReplies.error]: () => {
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          )
          this[vendorsViewActions.toggleRepeatPurchaseConfirmDialog]()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
  },
  mounted() {
    rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
      event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.getAllByPurchaseId.name,
      data: {
        purchaseOrderId: this.purchase._id,
      },
    })
    this.newPurchase.vendorId = this.selectedVendor.id
    this.newPurchase.cost = this.purchase.cost
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
    if (this.isOpen) this.closeDialog()
  },
}
</script>
