import { idOperations } from '@/config/cashOperationsVariables'

import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'
import { getDateWithFormat } from '@/tools/dates'
import { getOperationText, getOperationIcon } from '@/tools/cashOperationsTools'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const config = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: operation => methods.openOperationDetailDialog(operation),
    onDblClick: () => null,
  },
  containerRef: 'operations-view__operations-list',
  title: 'operationsView.listView.title',
  icon: 'mdi-cash-register',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  page: 1,
  rowOffsetHeight: 48,
  headers: [
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.operationsView.listView.date'
      ),
      align: 'start',
      value: 'date',
      icon: () => {
        return { icon: 'mdi-calendar' }
      },
      format: item => getDateWithFormat(item, 'DD-MM-YYYY HH:mm'),
      width: '20%',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.operationsView.listView.operationType'
      ),
      value: 'operationType',
      icon: value => getOperationIcon(value),
      format: (value, item, index) =>
        getOperationTypeFormat(state, methods, item, index),
      width: '30%',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.operationsView.listView.ticketNumber'
      ),
      value: 'ticketNumber',
      format: value => value,
      width: '20%',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.operationsView.listView.user'
      ),
      value: 'userId',
      icon: () => {
        return { icon: 'mdi-account' }
      },
      format: item => {
        return item === ''
          ? methods.getTranslatedText('operationsView.listView.unknownUser')
          : state.users.find(user => user._id == item)?.name || ''
      },
      width: '20%',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.operationsView.listView.amount'
      ),
      align: 'end',
      value: 'amount',
      format: item => formatNumberFromDbToCurrency(item),
      width: '10%',
    },
  ],
  sortBy: 'date',
  sortDesc: true,
  isClickable: true,
})

const getOperationTypeFormat = (state, methods, operation, index) => {
  if (
    operation.operationType === idOperations.ID_OPERATION_ADDCASH &&
    operation.relatedId !== -1
  ) {
    return getAddCashToPayText(methods, state.items, { operation, index })
  }
  if (
    operation.operationType ===
      idOperations.ID_OPERATION_EXTERNAL_PAYMENT_SALE &&
    operation.extraInfo
  ) {
    return methods.getTranslatedText(
      'operationsView.operationType.providerPaymentSale',
      operation.extraInfo
    )
  }
  return `${methods.getTranslatedText(
    getOperationText(operation.operationType)
  )}${getVendor(operation)}`
}

const getAddCashToPayText = (methods, operations, addCashOperation) => {
  const { operation, index } = addCashOperation
  if (operations[index - 1].id !== operation.relatedId) {
    return methods.getTranslatedText(
      'operationsView.operationType.addCashToPay'
    )
  }
  switch (operations[index - 1].operationType) {
    case idOperations.ID_OPERATION_CASH_PURCHASE:
      return `${methods.getTranslatedText(
        'operationsView.operationType.addCashToPayVendor'
      )}${getVendor(operations[index - 1])}`
    case idOperations.ID_OPERATION_EXPENSE:
      return methods.getTranslatedText(
        'operationsView.operationType.addCashToPayExpense'
      )
    default:
      return methods.getTranslatedText(
        'operationsView.operationType.addCashToPay'
      )
  }
}

const getVendor = operation => {
  if (!operation.vendor) {
    return ''
  }
  return ` (${operation.vendor})`
}

export default config
