import { activeOperations } from '@/config/cashOperationsVariables'

const config = (state, methods) => ({
  state,
  methods,
  groupClass: 'pr-4',
  groups: [
    {
      id: 'filters-group-01',
      controls: [
        {
          id: 'date-range-control',
          type: 'dateRange',
          label: 'operationsView.listView.dateRange',
          icon: 'mdi-calendar',
          backgroundColor: 'cardBackgroundSecondary',
          color: 'accent',
          ref: 'date-range-control',
          width: 325,
          value: state.filters.dateRange,
          onChange: value => methods.setDateRange(value),
        },
        {
          id: 'search-control',
          type: 'input',
          label: 'operationsView.listView.search',
          placeholder: 'operationsView.listView.searchTicketNumber',
          icon: 'mdi-magnify',
          backgroundColor: 'cardBackgroundSecondary',
          color: 'primary',
          ref: 'input-search-control',
          class: 'ml-4',
          group: 'search',
          onChange: methods.setSearchFilter,
        },
      ],
    },
    {
      id: 'filters-group-02',
      controls: [
        {
          id: 'all-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.all',
          icon: 'mdi-view-module',
          group: 'all',
          color:
            state.filters.group === 'all' ? 'accent lighten-1' : 'salesPrimary',
          onClick: () => {
            methods.setGroup('all')
          },
        },
        {
          id: 'charged-button-control',
          type: 'button',
          label: 'operationsView.listView.incomes',
          icon: 'mdi-cash-plus',
          group: 'charged',
          color:
            state.filters.group === 'charged'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: () => {
            methods.setGroup('charged')
          },
        },
        {
          id: 'paid-button-control',
          type: 'button',
          label: 'operationsView.listView.expenses',
          icon: 'mdi-cash-minus',
          group: 'paid',
          color:
            state.filters.group === 'paid'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: () => {
            methods.setGroup('paid')
          },
        },
        {
          id: 'noMoneyFlow-button-control',
          type: 'button',
          label: 'operationsView.listView.noMoneyFlow',
          icon: 'mdi-cash-remove',
          group: 'neutral',
          color:
            state.filters.group === 'neutral'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: () => {
            methods.setGroup('neutral')
          },
        },
      ],
    },
    {
      id: 'filters-group-03',
      controls: [
        {
          id: 'operationType-select-control',
          type: 'select',
          label: 'operationsView.listView.title',
          items: activeOperations,
          valuesSelected: state.filters.operationTypes,
          stringValueSelected: 'operationsView.listView.operationsSelected',
          itemValue: 'value',
          backgroundColor: 'cardBackgroundSecondary',
          width: 300,
          onChange: data => methods.setSelectedOperationTypes(data),
          onClick: () => {
            methods.setGroup('all')
          },
        },
      ],
    },
    {
      id: 'filters-group-04',
      controls: [
        {
          id: 'clear-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.clear',
          icon: 'mdi-close-circle',
          group: 'clear',
          color: 'accent',
          onClick: (resetSelector, resetSearchTerm) => {
            methods.initializeDateRangeFilter()
            methods.setGroup('all')
            methods.setSelectedOperationTypes([])
            methods.setSearchFilter('')
            resetSelector()
            resetSearchTerm()
          },
        },
      ],
    },
  ],
})

export default config
